# Let's find a Costas array of order 11 using backtracking with constraint checking
def find_costas_array(n):
    """Find a Costas array of order n using backtracking."""

    def is_valid_partial(perm):
        """Check if the partial permutation satisfies the Costas property so far."""
        # Check all pairs of displacement vectors
        vectors = set()
        for i in range(len(perm)):
            for j in range(i+1, len(perm)):
                dc = j - i
                dr = perm[j] - perm[i]
                vec = (dc, dr)
                if vec in vectors:
                    return False
                vectors.add(vec)
        return True

    def backtrack(perm, used_rows):
        if len(perm) == n:
            return perm

        for row in range(n):
            if row not in used_rows:
                perm.append(row)
                used_rows.add(row)

                if is_valid_partial(perm):
                    result = backtrack(perm, used_rows)
                    if result is not None:
                        return result

                perm.pop()
                used_rows.remove(row)

        return None

    return backtrack([], set())

# Try to find a Costas array of order 11
result = find_costas_array(11)
if result:
    print("Found Costas array:", result)
else:
    print("No Costas array found (might need more time or different approach)")
